import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const DEFAULT_FILE = resolve(process.cwd(), 'data/books.json');

/** Turn a title into a short, readable, URL-safe id like "the-hobbit-4f9a". */
function makeId(title) {
  const slug = String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 40);
  const suffix = randomBytes(2).toString('hex');
  return slug ? `${slug}-${suffix}` : suffix;
}

/**
 * The books, kept in a JSON file on disk.
 *
 * Every write goes through `#queue` so two overlapping requests can't
 * read-modify-write on top of each other, and lands via a temp file + rename so a
 * crash mid-write can't leave a half-written books.json behind.
 */
export class BookStore {
  #file;
  #queue = Promise.resolve();

  constructor(file = process.env.BOOKS_FILE || DEFAULT_FILE) {
    this.#file = resolve(file);
  }

  get file() {
    return this.#file;
  }

  async #read() {
    let raw;
    try {
      raw = await readFile(this.#file, 'utf8');
    } catch (err) {
      if (err.code === 'ENOENT') return []; // first run
      throw err;
    }
    if (!raw.trim()) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  }

  async #write(books) {
    await mkdir(dirname(this.#file), { recursive: true });
    const tmp = `${this.#file}.${process.pid}.tmp`;
    await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`);
    await rename(tmp, this.#file);
  }

  /** Serialise a read-modify-write against the file. */
  #update(fn) {
    const next = this.#queue.then(async () => {
      const books = await this.#read();
      const result = await fn(books);
      await this.#write(books);
      return result;
    });
    // Keep the chain alive even if this update rejects.
    this.#queue = next.catch(() => {});
    return next;
  }

  /** All books, newest addition first. */
  async all() {
    const books = await this.#read();
    return books.slice().sort((a, b) => String(b.addedAt).localeCompare(String(a.addedAt)));
  }

  /** `{ reading, finished }` — what the home page shows. */
  async shelves() {
    const books = await this.all();
    return {
      reading: books.filter((b) => b.status !== 'finished'),
      finished: books
        .filter((b) => b.status === 'finished')
        .sort((a, b) => String(b.finishedAt).localeCompare(String(a.finishedAt))),
    };
  }

  async get(id) {
    const books = await this.#read();
    return books.find((b) => b.id === id) ?? null;
  }

  /**
   * Add a book. Title is required; author and notes are optional.
   * Throws an Error with `.field` set when the input is unusable.
   */
  add({ title, author = '', notes = '' } = {}) {
    const cleanTitle = String(title ?? '').trim();
    if (!cleanTitle) {
      const err = new Error('A title is required.');
      err.field = 'title';
      throw err;
    }
    return this.#update((books) => {
      const book = {
        id: makeId(cleanTitle),
        title: cleanTitle,
        author: String(author ?? '').trim(),
        notes: String(notes ?? '').trim(),
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      return book;
    });
  }

  /** Mark a book finished. Returns the book, or null if the id is unknown. */
  finish(id) {
    return this.#update((books) => {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
      return book;
    });
  }

  /** Move a finished book back to currently-reading. */
  reopen(id) {
    return this.#update((books) => {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.status = 'reading';
      book.finishedAt = null;
      return book;
    });
  }

  /** Replace a book's notes. Returns the book, or null if the id is unknown. */
  setNotes(id, notes) {
    return this.#update((books) => {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      book.notes = String(notes ?? '').trim();
      return book;
    });
  }
}

