/** HTML rendering. Everything user-typed goes through `escape()` on the way out. */

export function escape(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

const CSS = `
  :root {
    color-scheme: light dark;
    --bg: #fbfaf8;
    --panel: #ffffff;
    --text: #23201d;
    --muted: #6f6862;
    --line: #e5e0d8;
    --accent: #7a4b2a;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #1a1816;
      --panel: #232120;
      --text: #ece8e3;
      --muted: #a39b93;
      --line: #38342f;
      --accent: #d9a273;
    }
  }
  * { box-sizing: border-box; }
  body {
    margin: 0 auto;
    padding: 2.5rem 1.25rem 4rem;
    max-width: 46rem;
    background: var(--bg);
    color: var(--text);
    font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  }
  a { color: var(--accent); }
  h1 { font-size: 1.6rem; margin: 0 0 1.75rem; letter-spacing: -0.01em; }
  h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.09em;
       color: var(--muted); margin: 2.25rem 0 0.75rem; }
  ul.shelf { list-style: none; margin: 0; padding: 0; }
  ul.shelf li {
    display: flex; align-items: baseline; gap: 0.75rem;
    padding: 0.7rem 0; border-bottom: 1px solid var(--line);
  }
  ul.shelf li .grow { flex: 1; min-width: 0; }
  ul.shelf a.title { font-weight: 600; text-decoration: none; }
  ul.shelf a.title:hover { text-decoration: underline; }
  .byline, .empty, .meta { color: var(--muted); }
  .byline { font-size: 0.9rem; }
  .empty { font-style: italic; padding: 0.7rem 0; }
  .meta { font-size: 0.85rem; }
  form.inline { margin: 0; }
  button {
    font: inherit; cursor: pointer; border-radius: 6px;
    border: 1px solid var(--line); background: var(--panel); color: var(--text);
    padding: 0.3rem 0.7rem; font-size: 0.85rem;
  }
  button:hover { border-color: var(--accent); color: var(--accent); }
  button.primary {
    background: var(--accent); border-color: var(--accent); color: var(--bg);
    padding: 0.55rem 1.1rem; font-size: 0.95rem;
  }
  button.primary:hover { color: var(--bg); opacity: 0.9; }
  .card {
    background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
    padding: 1.25rem; margin-top: 0.5rem;
  }
  label { display: block; font-size: 0.85rem; color: var(--muted); margin-bottom: 0.25rem; }
  input, textarea {
    font: inherit; width: 100%; padding: 0.5rem 0.6rem; margin-bottom: 0.9rem;
    border: 1px solid var(--line); border-radius: 6px;
    background: var(--bg); color: var(--text);
  }
  textarea { min-height: 6rem; resize: vertical; }
  input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
  .error { color: #c0392b; margin: 0 0 1rem; }
  @media (prefers-color-scheme: dark) { .error { color: #ff8f7a; } }
  .back { display: inline-block; margin-bottom: 1.5rem; font-size: 0.9rem; }
  .notes { white-space: pre-wrap; margin: 0; }
  .pill {
    font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.07em;
    color: var(--muted); border: 1px solid var(--line);
    border-radius: 999px; padding: 0.15rem 0.55rem;
  }
  .actions { display: flex; gap: 0.5rem; margin-top: 1.5rem; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>${CSS}</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function shortDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

function shelfItem(book, action) {
  return `  <li>
    <span class="grow">
      <a class="title" href="/books/${escape(book.id)}">${escape(book.title)}</a>
      ${book.author ? `<div class="byline">${escape(book.author)}</div>` : ''}
    </span>
    ${action}
  </li>`;
}

/** Home page: currently reading, finished, and the add-a-book form. */
export function renderHome({ reading, finished }, form = {}) {
  const readingItems = reading.length
    ? `<ul class="shelf">
${reading
  .map((b) =>
    shelfItem(
      b,
      `<form class="inline" method="post" action="/books/${escape(b.id)}/finish">
      <button type="submit">Mark finished</button>
    </form>`
    )
  )
  .join('\n')}
</ul>`
    : `<p class="empty">Nothing on the go right now — add a book below.</p>`;

  const finishedItems = finished.length
    ? `<ul class="shelf">
${finished
  .map((b) => shelfItem(b, `<span class="meta">${escape(shortDate(b.finishedAt))}</span>`))
  .join('\n')}
</ul>`
    : `<p class="empty">No finished books yet.</p>`;

  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${readingItems}

<h2>Finished</h2>
${finishedItems}

<h2>Add a book</h2>
<form class="card" method="post" action="/books">
  ${form.error ? `<p class="error">${escape(form.error)}</p>` : ''}
  <label for="title">Title</label>
  <input id="title" name="title" value="${escape(form.title)}" required autofocus>
  <label for="author">Author</label>
  <input id="author" name="author" value="${escape(form.author)}">
  <label for="notes">Notes <span class="meta">(optional)</span></label>
  <textarea id="notes" name="notes">${escape(form.notes)}</textarea>
  <button class="primary" type="submit">Add book</button>
</form>`
  );
}

/** A single book — the page a shared link opens. */
export function renderBook(book) {
  const status =
    book.status === 'finished'
      ? `<span class="pill">Finished${
          shortDate(book.finishedAt) ? ` ${escape(shortDate(book.finishedAt))}` : ''
        }</span>`
      : `<span class="pill">Reading</span>`;

  const action =
    book.status === 'finished'
      ? `<form class="inline" method="post" action="/books/${escape(book.id)}/reopen">
    <button type="submit">Move back to reading</button>
  </form>`
      : `<form class="inline" method="post" action="/books/${escape(book.id)}/finish">
    <button type="submit">Mark finished</button>
  </form>`;

  return layout(
    book.title,
    `<a class="back" href="/">&larr; All books</a>

<h1>${escape(book.title)}</h1>
<p class="byline">${book.author ? escape(book.author) : 'Author unknown'} &middot; ${status}</p>

<h2>Notes</h2>
<form class="card" method="post" action="/books/${escape(book.id)}/notes">
  <textarea name="notes" aria-label="Notes">${escape(book.notes)}</textarea>
  <button class="primary" type="submit">Save notes</button>
</form>

<div class="actions">${action}</div>`
  );
}

export function renderNotFound() {
  return layout(
    'Not found',
    `<h1>Not found</h1>
<p class="empty">That book isn't on the shelf.</p>
<a class="back" href="/">&larr; All books</a>`
  );
}

