import { BookStore } from './store.mjs';
import { renderBook, renderHome, renderNotFound } from './views.mjs';

const MAX_BODY = 64 * 1024; // plenty for a form; keeps a runaway POST from filling memory

function html(res, status, body) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'cache-control': 'no-store',
  });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

/** Only same-site absolute paths are allowed back out of a redirect field. */
function safePath(value, fallback = '/') {
  const path = String(value ?? '');
  return /^\/(?!\/)[\w\-/]*$/.test(path) ? path : fallback;
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) {
      req.destroy();
      throw Object.assign(new Error('Form data too large.'), { status: 413 });
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

/**
 * Build the request handler. Pages are rendered on the server, so every book has a
 * real URL (`/books/:id`) that can be pasted to someone else.
 */
export function createApp(store = new BookStore()) {
  return async function handle(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const method = req.method === 'HEAD' ? 'GET' : req.method;

    try {
      if (pathname === '/' && method === 'GET') {
        return html(res, 200, renderHome(await store.shelves()));
      }

      if (pathname === '/books' && method === 'POST') {
        const form = await readForm(req);
        const draft = {
          title: form.get('title') ?? '',
          author: form.get('author') ?? '',
          notes: form.get('notes') ?? '',
        };
        try {
          await store.add(draft);
        } catch (err) {
          if (!err.field) throw err;
          // Re-render the form with what they typed rather than losing it.
          return html(res, 400, renderHome(await store.shelves(), { ...draft, error: err.message }));
        }
        return redirect(res, '/');
      }

      const match = pathname.match(/^\/books\/([^/]+)(?:\/(finish|reopen|notes))?$/);
      if (match) {
        const id = decodeURIComponent(match[1]);
        const action = match[2];

        if (!action) {
          if (method !== 'GET') return html(res, 405, renderNotFound());
          const book = await store.get(id);
          return book ? html(res, 200, renderBook(book)) : html(res, 404, renderNotFound());
        }

        if (method !== 'POST') return html(res, 405, renderNotFound());
        const form = await readForm(req);
        const book =
          action === 'finish'
            ? await store.finish(id)
            : action === 'reopen'
              ? await store.reopen(id)
              : await store.setNotes(id, form.get('notes') ?? '');

        if (!book) return html(res, 404, renderNotFound());
        const fallback = action === 'notes' ? `/books/${encodeURIComponent(id)}` : '/';
        return redirect(res, safePath(form.get('redirect'), fallback));
      }

      return html(res, 404, renderNotFound());
    } catch (err) {
      const status = err.status ?? 500;
      if (status === 500) console.error(err);
      return html(res, status, renderNotFound());
    }
  };
}

