import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { beforeEach, describe, expect, it } from 'vitest';

import { BookStore } from '../src/store.mjs';

let store;
let file;

beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
  store = new BookStore(file);
});

describe('BookStore', () => {
  it('starts empty when the file does not exist yet', async () => {
    expect(await store.all()).toEqual([]);
    expect(await store.shelves()).toEqual({ reading: [], finished: [] });
  });

  it('adds a book as currently reading and gives it a shareable id', async () => {
    const book = await store.add({ title: 'The Hobbit', author: 'Tolkien', notes: 'ch. 3' });

    expect(book.status).toBe('reading');
    expect(book.id).toMatch(/^the-hobbit-[0-9a-f]{4}$/);
    expect(await store.get(book.id)).toMatchObject({ title: 'The Hobbit', notes: 'ch. 3' });
  });

  it('requires a title', async () => {
    await expect(store.add({ title: '   ', author: 'Nobody' })).rejects.toThrow(/title/i);
    expect(await store.all()).toEqual([]);
  });

  it('gives distinct ids to books with the same title', async () => {
    const a = await store.add({ title: 'Dune' });
    const b = await store.add({ title: 'Dune' });
    expect(a.id).not.toBe(b.id);
  });

  it('persists across instances', async () => {
    const { id } = await store.add({ title: 'Piranesi' });
    expect(await new BookStore(file).get(id)).toMatchObject({ title: 'Piranesi' });
  });

  it('moves a book between shelves', async () => {
    const { id } = await store.add({ title: 'Middlemarch' });

    const finished = await store.finish(id);
    expect(finished.status).toBe('finished');
    expect(finished.finishedAt).toBeTruthy();

    let shelves = await store.shelves();
    expect(shelves.reading).toHaveLength(0);
    expect(shelves.finished.map((b) => b.id)).toEqual([id]);

    await store.reopen(id);
    shelves = await store.shelves();
    expect(shelves.reading.map((b) => b.id)).toEqual([id]);
    expect(shelves.finished).toHaveLength(0);
  });

  it('returns null for actions on an unknown id', async () => {
    expect(await store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.setNotes('nope', 'hi')).toBeNull();
  });

  it('replaces notes', async () => {
    const { id } = await store.add({ title: 'Ulysses', notes: 'first pass' });
    await store.setNotes(id, '  second pass  ');
    expect((await store.get(id)).notes).toBe('second pass');
  });

  it('keeps every write when they overlap', async () => {
    const titles = ['A', 'B', 'C', 'D', 'E'];
    await Promise.all(titles.map((title) => store.add({ title })));

    const saved = JSON.parse(await readFile(file, 'utf8'));
    expect(saved.map((b) => b.title).sort()).toEqual(titles);
  });

  it('tolerates an empty data file', async () => {
    await writeFile(file, '');
    expect(await store.all()).toEqual([]);
  });
});

