import { createServer } from 'node:http';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { createApp } from '../src/app.mjs';
import { BookStore } from '../src/store.mjs';

let server;
let base;
let store;

beforeEach(async () => {
  const dir = await mkdtemp(join(tmpdir(), 'books-app-'));
  store = new BookStore(join(dir, 'books.json'));
  server = createServer(createApp(store));
  await new Promise((done) => server.listen(0, done));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(() => new Promise((done) => server.close(done)));

const get = (path) => fetch(`${base}${path}`);

const post = (path, fields) =>
  fetch(`${base}${path}`, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
  });

describe('the app', () => {
  it('shows both shelves on the home page', async () => {
    const res = await get('/');
    const body = await res.text();

    expect(res.status).toBe(200);
    expect(body).toContain('Currently reading');
    expect(body).toContain('Finished');
    expect(body).toContain('Add a book');
  });

  it('adds a book from the form and lists it', async () => {
    const res = await post('/books', { title: 'Wolf Hall', author: 'Mantel', notes: 'slow start' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const body = await (await get('/')).text();
    expect(body).toContain('Wolf Hall');
    expect(body).toContain('Mantel');
  });

  it('re-renders the form with the input when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Mantel' });
    const body = await res.text();

    expect(res.status).toBe(400);
    expect(body).toContain('A title is required.');
    expect(body).toContain('value="Mantel"');
  });

  it('serves a single book at its own URL, with author and notes', async () => {
    const { id } = await store.add({ title: 'Solaris', author: 'Lem', notes: 'the ocean' });

    const res = await get(`/books/${id}`);
    const body = await res.text();

    expect(res.status).toBe(200);
    expect(body).toContain('Solaris');
    expect(body).toContain('Lem');
    expect(body).toContain('the ocean');
  });

  it('marks a book finished from the list and from the book page', async () => {
    const a = await store.add({ title: 'Beloved' });
    const b = await store.add({ title: 'Stoner' });

    const fromList = await post(`/books/${a.id}/finish`, {});
    expect(fromList.headers.get('location')).toBe('/');
    expect((await store.get(a.id)).status).toBe('finished');

    const fromPage = await post(`/books/${b.id}/finish`, { redirect: `/books/${b.id}` });
    expect(fromPage.headers.get('location')).toBe(`/books/${b.id}`);
    expect((await store.get(b.id)).status).toBe('finished');
  });

  it('saves notes from the book page', async () => {
    const { id } = await store.add({ title: 'Kafka on the Shore' });

    const res = await post(`/books/${id}/notes`, { notes: 'the cats talk' });
    expect(res.headers.get('location')).toBe(`/books/${id}`);
    expect((await store.get(id)).notes).toBe('the cats talk');
  });

  it('reopens a finished book', async () => {
    const { id } = await store.add({ title: 'Anna Karenina' });
    await store.finish(id);

    await post(`/books/${id}/reopen`, {});
    expect((await store.get(id)).status).toBe('reading');
  });

  it('404s for an unknown book', async () => {
    const res = await get('/books/not-a-real-book');
    expect(res.status).toBe(404);
    expect(await res.text()).toContain("isn't on the shelf");
  });

  it('ignores an off-site redirect target', async () => {
    const { id } = await store.add({ title: 'Redirect Bait' });
    const res = await post(`/books/${id}/finish`, { redirect: 'https://evil.example.com/' });
    expect(res.headers.get('location')).toBe('/');
  });

  it('escapes HTML in what I type', async () => {
    await store.add({ title: '<script>alert(1)</script>', author: 'x' });
    const body = await (await get('/')).text();

    expect(body).not.toContain('<script>alert(1)</script>');
    expect(body).toContain('&lt;script&gt;');
  });
});

